from torch.utils.cpp_extension import load_inline

# Define CUDA kernel for matrix multiplication using warp-level matrix operations
cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cooperative_groups.h>
#include <cooperative_groups/reduce.h>

namespace cg = cooperative_groups;

#define TILE_SIZE 32

__global__ void matmul_kernel(const float* A, const float* B, float* C, int N) {
    cg::thread_block block = cg::this_thread_block();
    cg::thread_block_tile<32> warp = cg::tiled_partition<32>(block);

    __shared__ float As[TILE_SIZE][TILE_SIZE];
    __shared__ float Bs[TILE_SIZE][TILE_SIZE];

    int warpId = threadIdx.y;
    int laneId = threadIdx.x;

    int row = (blockIdx.y * TILE_SIZE) + warpId;
    int col = (blockIdx.x * TILE_SIZE) + laneId;

    float sum = 0.0f;

    for (int tile = 0; tile < (N + TILE_SIZE - 1) / TILE_SIZE; tile++) {
        // Load tile of A into shared memory
        int a_col = tile * TILE_SIZE + laneId;
        if (row < N && a_col < N) {
            As[warpId][laneId] = A[row * N + a_col];
        } else {
            As[warpId][laneId] = 0.0f;
        }

        // Load tile of B into shared memory
        int b_row = tile * TILE_SIZE + warpId;
        if (b_row < N && col < N) {
            Bs[warpId][laneId] = B[b_row * N + col];
        } else {
            Bs[warpId][laneId] = 0.0f;
        }

        block.sync();

        // Warp-level matrix multiplication
        for (int k = 0; k < TILE_SIZE; k++) {
            float a_val = As[warpId][k];
            float b_val = Bs[k][laneId];
            sum += a_val * b_val;
        }

        block.sync();
    }

    // Write result to global memory
    if (row < N && col < N) {
        C[row * N + col] = sum;
    }
}

