    int M = A.size(1);
    int P = B.size(1);

    // Check matrix dimensions
    TORCH_CHECK(M == B.size(0), "Matrix dimensions mismatch");
    TORCH_CHECK(N == P, "Output matrix must be square");

    auto C = torch::zeros({N, P}, A.options());

    // Set grid and block dimensions
    dim3 threadsPerBlock(32, 32);
    dim3 numBlocks((P + TILE_SIZE - 1) / TILE_SIZE,
                   (N + TILE_SIZE - 1) / TILE_SIZE);

    // Launch kernel
    matmul_kernel<<<numBlocks, threadsPerBlock>>>(A.data_ptr<float>(), 
                                                B.data_ptr<float>(), 
                                                C.data_ptr<float>(), 
                                                N);

    return C;
}
"""

